function FeaturedProjects({items=[]}){
 if(!items.length)return null;
 return <section className="section featured-projects"><div className="section-head"><div><Label>SELECTED PROJECTS / PUBLISHED WORK</Label><h2>Digital work,<br/>put into practice<span>.</span></h2></div><p>Published project entries from the studio portfolio. Project type and delivery status are identified clearly.</p></div><div className="featured-project-grid">{items.map((item,i)=>{const data=item.data||{},image=typeof data.cover_image_url==='string'&&/^https:\/\//i.test(data.cover_image_url)?data.cover_image_url:'',url=typeof data.live_url==='string'&&/^https:\/\//i.test(data.live_url)?data.live_url:'';const content=<><div className="featured-project-image">{image?<img src={image} alt={data.image_alt||item.title} loading="lazy"/>:<span>{String(i+1).padStart(2,'0')}</span>}</div><div className="featured-project-copy"><small>{data.project_type||'DIGITAL PROJECT'} / {data.delivery_status||'PUBLISHED ENTRY'}</small><h3>{item.title}</h3><p>{item.summary}</p><span>{data.industry||'DIGITAL DEVELOPMENT'} <b>↗</b></span></div></>;return url?<a className="featured-project" href={url} target="_blank" rel="noreferrer" key={item.id}>{content}</a>:<article className="featured-project" key={item.id}>{content}</article>;})}</div></section>;
}
function TestimonialsSection({items=[]}){
 if(!items.length)return null;
 return <section className="section testimonials"><div className="section-head"><div><Label>CLIENT PERSPECTIVES</Label><h2>Trust is built<br/>through the work<span>.</span></h2></div><p>Only feedback that has been explicitly verified and approved is shown here.</p></div><div className="testimonial-grid">{items.map(item=><blockquote key={item.id}><p>“{item.data?.quote||item.summary}”</p><footer><strong>{item.data?.author_name||item.title}</strong><span>{[item.data?.author_role,item.data?.company_name].filter(Boolean).join(' · ')}</span></footer></blockquote>)}</div></section>;
}
function PageIntro({eyebrow,title,desc}){return <section className="page-intro"><Label>{eyebrow}</Label><h1>{title}</h1>{desc&&<p>{desc}</p>}</section>}
function Services({cms}){return <><PageIntro eyebrow="CAPABILITIES / WHAT WE DO" title="Digital solutions with a job to do." desc="From a stronger business website to a custom digital system, we bring strategy, design and engineering together around practical outcomes."/><section className="section"><ServiceGrid items={cms?.services}/></section><section className="section pricing"><Label>COMMERCIAL APPROACH</Label><h2>Build. Maintain. Expand<span>.</span></h2><div className="pricing-grid"><div><small>01 / BUILD</small><h3>Once-off development</h3><p>Defined project scope, deliverables and milestones. Website projects may start from R3,500, subject to requirements and final quotation.</p></div><div><small>02 / MAINTAIN</small><h3>Monthly website care</h3><p>Ongoing support with agreed limits. Care plans may start from R250 per month, depending on coverage and responsibility.</p></div><div><small>03 / EXPAND</small><h3>Continuous improvement</h3><p>New functionality, integrations, automation and larger digital systems as your needs evolve.</p></div></div><p className="fineprint">Starting prices are indicative, not binding offers. Domain registration, hosting, premium licences, third-party services, payment processing and out-of-scope work are quoted separately unless stated otherwise.</p></section><CTA/></>}
function DynamicPage({page}){
 const data=page.data||{},sections=Array.isArray(data.sections)?data.sections:[];
 return <><PageIntro eyebrow={data.eyebrow||'NOCTRA HOURS / DIGITAL DEVELOPMENT'} title={page.title} desc={page.summary}/>{sections.map((section,i)=><section className="section dynamic-page-section" key={i}><Label>{section.eyebrow||String(i+1).padStart(2,'0')+' / '+page.title.toUpperCase()}</Label>{section.heading&&<h2>{section.heading}</h2>}{section.body&&<p>{section.body}</p>}</section>)}<CTA/></>;
}
function ServiceDetail({data}){return <><PageIntro eyebrow={data.eyebrow} title={data.title} desc={data.intro}/><section className="section detail-layout"><div><Label>THE APPROACH</Label><p className="lead">{data.body}</p><A href="/contact" className="button">Discuss this service ↗</A></div><div><Label>WHAT WE CAN BUILD</Label><ul className="check-list">{data.items.map(x=><li key={x}>{x}<span>↗</span></li>)}</ul></div></section><section className="section faq"><Label>COMMON QUESTIONS</Label><h2>Before we begin<span>.</span></h2>{data.faqs.map(([q,a])=><details key={q}><summary>{q}<span>+</span></summary><p>{a}</p></details>)}</section><CTA/></>}
function Work({cms}){return <><PageIntro eyebrow="DIGITAL WORK / CATALOGUE" title="The right digital product for the job." desc="Not every business needs the same thing. Explore six distinct types of digital experiences, from a focused landing page to a connected business system or installable application."/><section className="section work-catalogue-page"><div className="work-catalogue-note"><span>HOW TO READ THIS CATALOGUE</span><p>These are capability studies showing the structure and direction of different project types. They are illustrative concepts, not claims of commissioned client work or completed deployments.</p></div><WorkCatalogue/><FeaturedProjects items={cms?.projects}/><div className="work-catalogue-end"><Label>HAVE A REQUIREMENT THAT DOESN'T FIT A CATEGORY?</Label><h2>Let's define what<br/>the solution needs to do<span>.</span></h2><A href="/contact" className="button">Discuss your project <span>↗</span></A></div></section><CTA/></>}function About(){return <><PageIntro eyebrow="ABOUT / NOCTRA HOURS" title="We believe technology should move business forward." desc="Noctra Hours is an independent digital development studio focused on creating purposeful digital experiences and practical technology solutions."/><section className="section detail-layout"><div><Label>OUR PERSPECTIVE</Label><p className="lead">We bring together strategic thinking, thoughtful design and modern development to help businesses establish stronger digital foundations.</p></div><div><p>Our work is guided by precision over complexity, functionality before decoration and strategy before development. We believe good technology should make the next step clearer—not add another layer of friction.</p><p>We work with businesses that want to establish a stronger digital presence, improve customer interactions or make the way they operate more connected.</p><p>Based in Giyani, Limpopo, our initial focus is the businesses and communities of the region, with a view to serving organisations across South Africa.</p></div></section><section className="section values"><Label>OUR PRINCIPLES</Label>{['Precision over complexity','Functionality before decoration','Strategy before development','Performance by design','Long-term digital partnerships'].map((x,i)=><div key={x}><span>0{i+1}</span>{x}</div>)}</section><CTA/></>}
function Process(){return <><PageIntro eyebrow="PROCESS / HOW WE WORK" title="A considered approach. A clear process." desc="A transparent delivery process creates shared understanding, better decisions and a stronger result."/><section className="section process-full">{process.map(([n,t,d])=><article key={n}><span>{n}</span><div><h2>{t}</h2><p>{d}</p></div><small>NOCTRA / DELIVERY</small></article>)}</section><CTA/></>}
function Insights(){return <><PageIntro eyebrow="INSIGHTS / FIELD NOTES" title="A clearer view of digital." desc="Practical perspectives on building, improving and maintaining digital experiences for growing businesses."/><section className="section insight-list">{[['01','What should a business website actually do?','A useful website does more than display information. It helps the right customer understand your value and take the next step.'],['02','Planning an online store before choosing a platform','Catalogue structure, fulfilment, payments and customer support should shape the platform decision—not the other way around.'],['03','When does a business need a custom digital system?','A custom system becomes worth exploring when repeated manual work, disconnected information or rigid tools create a measurable operational constraint.']].map(([n,t,d])=><article key={n}><span>{n} / FIELD NOTE</span><h2>{t}</h2><p>{d}</p><small>EDITORIAL / NOCTRA HOURS</small></article>)}</section><CTA/></>}
function Contact({config={}}){const [state,setState]=useState('idle');const [error,setError]=useState('');const siteKey=config.turnstileSiteKey||'';const formReady=Boolean(config.enquiryFormReady);const turnstileRef=useRef(null);useEffect(()=>{if(!siteKey||!formReady)return;const timer=setInterval(()=>{if(window.turnstile&&turnstileRef.current&&!turnstileRef.current.dataset.rendered){window.turnstile.render(turnstileRef.current,{sitekey:siteKey});turnstileRef.current.dataset.rendered='true';clearInterval(timer);}},250);return()=>clearInterval(timer);},[siteKey,formReady]);async function submit(e){e.preventDefault();const formElement=e.currentTarget;setState('sending');setError('');const form=new FormData(formElement);const payload=Object.fromEntries(form.entries());payload.privacy_consent=form.get('privacy_consent')==='on';payload.turnstile_token=form.get('cf-turnstile-response')||'';try{const r=await fetch('/api/enquiries',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});const data=await r.json().catch(()=>({}));if(!r.ok)throw new Error(data.error||'Your enquiry could not be submitted. Please try again.');setState('success');formElement.reset();}catch(err){setError(err.message);setState('error');}}return <><PageIntro eyebrow="CONTACT / START A PROJECT" title="Let's discuss what you're building." desc="Tell us about your business, your requirements and what you want to achieve. We'll review your enquiry and discuss the appropriate next steps."/><section className="section contact-layout"><div><Label>PROJECT ENQUIRY</Label><h2>A good project<br/>starts with a clear<br/>conversation<span>.</span></h2><p>Share what you know so far. You do not need every detail figured out before getting in touch.</p><div className="contact-note"><small>BASED IN</small><strong>Giyani, Limpopo<br/>South Africa</strong>{config.contactEmail&&<p><a href={'mailto:'+config.contactEmail}>{config.contactEmail}</a></p>}{config.whatsappUrl&&<p><a href={config.whatsappUrl} target="_blank" rel="noreferrer">Chat on WhatsApp ↗</a></p>}</div></div><form className="contact-form" onSubmit={submit}><label className="honeypot" aria-hidden="true">Leave this field empty<input name="website" tabIndex="-1" autoComplete="off"/></label><div className="form-grid"><label>Full name *<input name="full_name" required minLength="2" maxLength="120" autoComplete="name"/></label><label>Business name<input name="business_name" maxLength="160" autoComplete="organization"/></label><label>Email address *<input type="email" name="email" required maxLength="254" autoComplete="email"/></label><label>WhatsApp number<input name="whatsapp" maxLength="40" autoComplete="tel"/></label><label>Industry<select name="industry" defaultValue=""><option value="">Select industry</option>{industries.map(x=><option key={x}>{x}</option>)}</select></label><label>Service required *<select name="service_required" required defaultValue=""><option value="">Choose a service</option>{['Web development','E-commerce','Digital systems','Website care','Not sure yet'].map(x=><option key={x}>{x}</option>)}</select></label><label className="wide">Tell us about the project *<textarea name="project_description" required minLength="20" maxLength="5000" rows="5" placeholder="What are you looking to build or improve?"/></label><label>Estimated budget<select name="estimated_budget" defaultValue=""><option value="">Not sure yet</option>{['Under R3,500','R3,500 – R5,500','R5,500 – R8,500','R8,500 – R12,000','R12,000+','To be discussed'].map(x=><option key={x}>{x}</option>)}</select></label><label>Desired timeline<select name="desired_timeline" defaultValue=""><option value="">Flexible</option>{['As soon as possible','Within 1 month','1–3 months','3–6 months','Planning / research'].map(x=><option key={x}>{x}</option>)}</select></label><label>Preferred contact method<select name="preferred_contact_method" defaultValue="Email"><option>Email</option><option>WhatsApp</option><option>Phone</option></select></label><label className="consent wide"><input type="checkbox" name="privacy_consent" required/> I agree that Noctra Hours may use the information provided to review and respond to this project enquiry. See the <A href="/privacy-policy">privacy policy</A>.</label></div><div className="turnstile-holder">{formReady&&siteKey?<div className="cf-turnstile" ref={turnstileRef}></div>:<small>Secure project enquiries are being configured. Public contact details will appear here once supplied.</small>}</div><div className="form-submit"><button className="button" disabled={state==='sending'||!formReady}>{state==='sending'?'Sending…':'Submit project enquiry'} <span>↗</span></button><small>Fields marked * are required. Please do not submit passwords or sensitive personal information.</small></div>{state==='success'&&<p className="form-status success" role="status">Your enquiry has been received. Thank you for considering Noctra Hours.</p>}{state==='error'&&<p className="form-status error" role="alert">{error}</p>}</form></section></>}
function Legal({privacy=false}){return <><PageIntro eyebrow={privacy?'LEGAL / PRIVACY':'LEGAL / TERMS'} title={privacy?'Privacy is part of good practice.':'Clear expectations matter.'} desc={privacy?'This page explains how project enquiry information is handled.':'These general website terms describe the conditions for using the Noctra Hours website.'}/><section className="section legal"><h2>{privacy?'Information we collect':'Website use'}</h2><p>{privacy?'When you submit a project enquiry, we may collect your name, business details, contact information, project requirements and communication preferences.':'You may use this website for lawful information and enquiry purposes. Website content is provided for general information and may be updated as the business develops.'}</p><h2>{privacy?'Why we use it':'No offer or engagement'}</h2><p>{privacy?'Information is used to review and respond to your enquiry, assess project fit, communicate about requested services and maintain appropriate business records. We do not ask for passwords or unnecessary sensitive information.':'Submitting an enquiry does not create a client relationship, reserve capacity or constitute acceptance of a project. Work begins only after scope, fees, responsibilities and terms are agreed in writing.'}</p><h2>{privacy?'Storage and protection':'Intellectual property'}</h2><p>{privacy?'Enquiry information is intended to be stored in access-restricted systems and retained only as long as reasonably necessary for enquiry handling, business records and applicable legal obligations. Reasonable technical and organisational safeguards are used, although no online transmission or storage can be guaranteed completely secure.':'Unless otherwise agreed in writing, website text, design elements and materials remain the property of their respective owners. You may not copy or reuse protected materials without permission.'}</p><h2>{privacy?'Your choices':'Project agreements'}</h2><p>{privacy?'You may request access to or correction of personal information, or raise a privacy concern, by contacting Noctra Hours. This policy should be reviewed and updated with the final business contact details and retention procedure before launch.':'Any development engagement will be governed by a separate proposal, scope of work and service agreement covering deliverables, payment milestones, revisions, third-party costs, ownership, support and change requests.'}</p><h2>{privacy?'South African privacy principles':'Third-party services and availability'}</h2><p>{privacy?'Noctra Hours aims to handle personal information in accordance with the Protection of Personal Information Act (POPIA). Where applicable, you may request access to or correction of your information, object to processing, request deletion, or withdraw consent where consent is the lawful basis. Website infrastructure, database and transactional email providers may process information on the studio’s behalf, including in regions outside South Africa. Information will be retained only for a defined business or legal purpose and protected with reasonable safeguards. The final retention schedule and operator contact details must be completed before the enquiry form is enabled.':'This website may rely on third-party infrastructure, hosting, email, payment or software services. Their availability and terms are controlled by those providers. Noctra Hours does not guarantee uninterrupted website availability or the suitability of third-party services for a particular purpose. Any client project will have its own agreed scope, payment, ownership, warranty and support terms.'}</p><h2>Contact</h2><p>For questions about this page or a project enquiry, use the <A href="/contact">contact page</A>. These website terms and privacy disclosures should be reviewed against the final operating model before public launch.</p></section><CTA/></>}
function NotFound(){return <><PageIntro eyebrow="404 / NOT FOUND" title="This page isn't here." desc="The page may have moved, or the address may be incorrect."/><section className="section"><A href="/" className="button">Return home ↗</A></section></>}
export default function App(){const [siteConfig,setSiteConfig]=useState({});const [cmsContent,setCmsContent]=useState({});useEffect(()=>{fetch('/api/site-config',{headers:{accept:'application/json'}}).then(r=>r.ok?r.json():{}).then(setSiteConfig).catch(()=>{});},[]);useEffect(()=>{fetch('/api/public-content',{headers:{accept:'application/json'}}).then(r=>r.ok?r.json():{}).then(setCmsContent).catch(()=>{});},[]);const path=window.location.pathname.replace(/\/$/,'')||'/';const cmsSettings=cmsContent.settings||{};const publicConfig={...siteConfig,siteName:cmsSettings.site_identity?.name||'Noctra Hours',tagline:cmsSettings.site_identity?.tagline||'Digital infrastructure for ambitious businesses.',logoUrl:cmsSettings.site_identity?.logo_url||'',faviconUrl:cmsSettings.site_identity?.favicon_url||'',contactEmail:cmsSettings.contact?.email||siteConfig.contactEmail,whatsappUrl:(cmsSettings.contact?.whatsapp_number||cmsSettings.contact?.whatsappNumber)?'https://wa.me/'+String(cmsSettings.contact.whatsapp_number||cmsSettings.contact.whatsappNumber).replace(/\D/g,''):siteConfig.whatsappUrl,socialLinks:cmsContent.cms_available===true&&Array.isArray(cmsSettings.social_links)?cmsSettings.social_links:siteConfig.socialLinks};const dynamicPage=cmsContent.cms_available===true?cmsContent.pages?.find(item=>item.slug===path.replace(/^\//,'')):null;const [title,description]=routeMeta[path]||pages[path]?[...(routeMeta[path]||[pages[path].title+' | Noctra Hours',pages[path].intro])]:['Page not found | Noctra Hours','Return to the Noctra Hours homepage.'];const finalTitle=dynamicPage?.data?.seo_title||(path==='/'?(cmsSettings.seo_defaults?.title||title):title);const finalDescription=dynamicPage?.data?.seo_description||(path==='/'?(cmsSettings.seo_defaults?.description||description):description);useEffect(()=>{document.title=finalTitle;if(publicConfig.faviconUrl){let icon=document.head.querySelector('link[rel="icon"]');if(!icon){icon=document.createElement('link');icon.rel='icon';document.head.appendChild(icon);}icon.href=publicConfig.faviconUrl;}const tokens=cmsContent.cms_available===true?cmsSettings.brand_tokens||{}:{};const root=document.documentElement;const color=(value,fallback)=>/^#[0-9a-f]{6}$/i.test(String(value||''))?value:fallback;root.style.setProperty('--bg',color(tokens.background,'#101114'));root.style.setProperty('--surface',color(tokens.surface,'#191d25'));root.style.setProperty('--blue',color(tokens.accent,'#8bb8ff'));root.style.setProperty('--muted',color(tokens.muted,'#858c9a'));root.style.setProperty('--line',color(tokens.border,'#30343b'));const setMeta=(selector,attrs)=>{let el=document.head.querySelector(selector);if(!el){el=document.createElement('meta');document.head.appendChild(el);}Object.entries(attrs).forEach(([k,v])=>el.setAttribute(k,v));};setMeta('meta[name="description"]',{name:'description',content:finalDescription});setMeta('meta[property="og:title"]',{property:'og:title',content:finalTitle});setMeta('meta[property="og:description"]',{property:'og:description',content:finalDescription});setMeta('meta[property="og:type"]',{property:'og:type',content:'website'});setMeta('meta[name="twitter:card"]',{name:'twitter:card',content:'summary'});setMeta('meta[name="twitter:title"]',{name:'twitter:title',content:finalTitle});setMeta('meta[name="twitter:description"]',{name:'twitter:description',content:finalDescription});let schema=document.getElementById('noctra-business-schema');if(!schema){schema=document.createElement('script');schema.id='noctra-business-schema';schema.type='application/ld+json';document.head.appendChild(schema);}schema.textContent=JSON.stringify({'@context':'https://schema.org','@type':'ProfessionalService',name:publicConfig.siteName,description:publicConfig.tagline,url:(siteConfig.siteUrl||window.location.origin),'areaServed':[{'@type':'City',name:'Giyani'},{'@type':'AdministrativeArea',name:'Limpopo'},{'@type':'Country',name:'South Africa'}],address:{'@type':'PostalAddress',addressLocality:'Giyani',addressRegion:'Limpopo',addressCountry:'ZA'},serviceType:['Website development','E-commerce development','Custom digital systems','Website care']});setMeta('meta[property="og:url"]',{property:'og:url',content:(siteConfig.siteUrl||window.location.origin).replace(/\/$/,'')+path});let canonical=document.head.querySelector('link[rel="canonical"]');if(!canonical){canonical=document.createElement('link');canonical.rel='canonical';document.head.appendChild(canonical);}canonical.href=(siteConfig.siteUrl||window.location.origin).replace(/\/$/,'')+path;},[finalTitle,finalDescription,path,siteConfig.siteUrl,cmsSettings.seo_defaults,cmsSettings.brand_tokens,publicConfig.faviconUrl]);let content;if(path==='/')content=<Home cms={cmsContent}/>;else if(path==='/services')content=<Services cms={cmsContent.cms_available===true?cmsContent:undefined}/>;else if(pages[path])content=<ServiceDetail data={pages[path]}/>;else if(path==='/work')content=<Work cms={cmsContent.cms_available===true?cmsContent:undefined}/>;else if(path==='/about')content=<About/>;else if(path==='/process')content=<Process/>;else if(path==='/insights')content=<Insights/>;else if(path==='/contact')content=<Contact config={publicConfig}/>;else if(path==='/privacy-policy')content=<Legal privacy/>;else if(path==='/terms-of-service')content=<Legal/>;else if(dynamicPage)content=<DynamicPage page={dynamicPage}/>;else content=<NotFound/>;if(cmsContent.cms_available===true&&cmsSettings.maintenance_mode===true)return <main className="maintenance-screen"><Label>NOCTRA HOURS / MAINTENANCE</Label><h1>We’ll be back shortly.</h1><p>The website is temporarily unavailable while we make improvements.</p></main>;return <><a className="skip-link" href="#main-content">Skip to content</a><Header cms={cmsContent} config={publicConfig}/><main id="main-content">{content}</main><Footer config={publicConfig} cms={cmsContent.cms_available===true?cmsContent:undefined}/></>}
